fn addSupplementalResources(
    &mut self,
    mut resources: LegacyImportResourcesArchive,
    paths: &RuntimeStorePaths,
) -> Result<(), String> {
    let mut occupied = self.copyPlan.as_ref().into_iter()
        .flat_map(|plan| plan.items.iter().map(|item| item.targetPath.clone()))
        .collect::<HashSet<_>>();
    for item in &mut resources.items {
        let workspace = if matches!(item.location,
            LegacyImportResourceLocation::Public | LegacyImportResourceLocation::Internal) {
            item.relativePath.strip_prefix("workspace/")
                .filter(|relative| relative.contains('/'))
        } else { None };
        let target = if let Some(relative) = workspace {
            let (id, rest) = splitWorkspaceRelativePath(relative)?;
            if rest.is_empty() { continue; }
            let targetId = self.workspaceIds.entry(id.to_string())
                .or_insert_with(|| Uuid::new_v4().to_string());
            item.workspace = true;
            format!("{WORKSPACE_DIR_PATH}/{targetId}/{rest}")
        } else {
            let root = match item.location {
                LegacyImportResourceLocation::Public => format!("{}/public", self.importedExternalFilesRoot),
                LegacyImportResourceLocation::Internal => self.importedFilesRoot.clone(),
                LegacyImportResourceLocation::External => self.importedExternalFilesRoot.clone(),
                LegacyImportResourceLocation::Cache => format!("{}/cache", self.importedFilesRoot),
            };
            joinVirtualPath(&root, &item.relativePath)
        };
        let physical = if let Some(relative) = workspace {
            let (id, rest) = splitWorkspaceRelativePath(relative)?;
            paths.workspace_path(&self.workspaceIds[id]).join(rest)
                .to_string_lossy().into_owned()
        } else {
            paths.runtime_storage_path(&target).to_string_lossy().into_owned()
        };
        for prefix in item.sourcePrefixes(&self.legacyPackageName) {
            let mut sourcePath = format!("{prefix}{}", item.relativePath);
            let mut targetPath = physical.clone();
            // Only map directories evidenced by an actual archived child.
            // Workspaces use independently allocated IDs, so stop at that ID.
            let stop = if let Some(relative) = workspace {
                let (id, _) = splitWorkspaceRelativePath(relative)?;
                format!("{prefix}workspace/{id}")
            } else { prefix.trim_end_matches('/').to_string() };
            loop {
                for source in [format!("file://{sourcePath}"), sourcePath.clone()] {
                    if !self.resourcePaths.iter().any(|(existing, _)| existing == &source) {
                        self.resourcePaths.push((source, targetPath.clone()));
                    }
                }
                if sourcePath == stop { break; }
                let Some((parent, _)) = sourcePath.rsplit_once('/') else { break; };
                let Some((targetParent, _)) = targetPath.rsplit_once('/') else { break; };
                sourcePath = parent.to_string();
                targetPath = targetParent.to_string();
            }
        }
        // The snapshot wins when both files refer to the same destination.
        if occupied.insert(target.clone()) { item.targetPath = Some(target); }
    }
    self.resourcePaths.sort_by(|left, right| right.0.len().cmp(&left.0.len()));
    self.supplementalResources = Some(resources);
    Ok(())
}

fn rewriteResourceValue(&self, value: &mut Value) {
    match value {
        Value::String(text) => {
            let normalized = text.strip_prefix("file://").unwrap_or(text)
                .replace('\\', "/");
            if let Some((_, target)) = self.resourcePaths.iter()
                .find(|(source, _)| source == &normalized) {
                *text = target.clone();
            } else if normalized.contains("/workspace/") {
                if let Ok(target) = self.rewriteWorkspacePath(&normalized) {
                    if target != normalized { *text = target; return; }
                }
                *text = self.rewriteMessageContent(text);
            } else {
                *text = self.rewriteMessageContent(text);
            }
        }
        Value::Array(values) => values.iter_mut().for_each(|v| self.rewriteResourceValue(v)),
        Value::Object(values) => values.values_mut().for_each(|v| self.rewriteResourceValue(v)),
        _ => {}
    }
}

